//! Confusion group resolution for similar single-byte encodings.
//!
//! The distinguishing byte maps come from `confusion.bin` (generated by the
//! trainer): for each confusable encoding pair, which bytes the two read
//! differently and what Unicode general category each side's reading has. A
//! pair is decided by context-aware category voting, by re-scoring only the
//! distinguishing bigrams, or by requiring both to agree.
//!
//! This mirrors `chardet/pipeline/confusion.py`.

use crate::bigram_models::{get_models, ModelSet};
use crate::encoding_tables::{
    category_is_letter, category_is_lowercase, category_preference, differing_high_bytes,
    tables_for, EncodingTables,
};
use crate::pipeline::statistical::{score_with_profile, BigramProfile};
use crate::pipeline::DetectionResult;
use crate::registry::lookup_encoding;
use once_cell::sync::Lazy;
use std::collections::{HashMap, HashSet};

/// Maximum confidence gap from the top for candidates beyond position 1 to
/// participate in confusion resolution.
pub const CONFUSION_BAND: f64 = 0.005;

/// Minimum confidence, as a fraction of the top's, for out-of-band candidates
/// to enter the strict tier.
pub const CONFUSION_FLOOR_RATIO: f64 = 0.5;

/// The strict tier only opens below this top confidence.
pub const STRICT_TIER_MAX_CONF: f64 = 0.2;

/// Vote margin at which category voting overrides the bigram rescore.
const DECISIVE_VOTE_MARGIN: i32 = 8;

/// Minimum number of distinct demotion-earning occurrences for a decisive vote.
const DECISIVE_MIN_EVENTS: i32 = 2;

/// Cap on distinguishing-byte occurrences examined per pair.
const MAX_VOTE_OCCURRENCES: usize = 256;

/// Preference assigned to a letter reading whose context makes it implausible.
const IMPLAUSIBLE_LETTER_PREFERENCE: i32 = 2;

/// Distinguishing-set size at which a pair comes from the cross-family tier.
const CROSS_FAMILY_MIN_DIFFS: usize = 52;

/// The ANSI/ASCII-art pseudo-language; not up for linguistic review.
const ART_LANGUAGE: &str = "zxx";

/// One confusable encoding pair and the bytes it disagrees on.
pub struct PairMap {
    /// First encoding of the canonical pair key.
    pub enc_a: String,
    /// Second encoding of the canonical pair key.
    pub enc_b: String,
    /// Byte values the two encodings read differently.
    pub diff_bytes: Vec<u8>,
    member: [bool; 256],
    cat_a: [u8; 256],
    cat_b: [u8; 256],
}

impl PairMap {
    fn categories(&self, byte: u8) -> (u8, u8) {
        (self.cat_a[byte as usize], self.cat_b[byte as usize])
    }

    fn is_diff(&self, byte: u8) -> bool {
        self.member[byte as usize]
    }
}

/// Build a pair map from the generated decoding tables.
fn pair_from_tables(enc_a: &str, enc_b: &str, diff_bytes: &[u8]) -> PairMap {
    let mut member = [false; 256];
    for &byte in diff_bytes {
        member[byte as usize] = true;
    }
    let cat_a = tables_for(enc_a).map_or([29u8; 256], |table| table.category);
    let cat_b = tables_for(enc_b).map_or([29u8; 256], |table| table.category);
    PairMap {
        enc_a: enc_a.to_string(),
        enc_b: enc_b.to_string(),
        diff_bytes: diff_bytes.to_vec(),
        member,
        cat_a,
        cat_b,
    }
}

const CONFUSION_BIN: &[u8] = include_bytes!("../../../src/chardet/models/confusion.bin");

static CONFUSION_MAPS: Lazy<HashMap<(String, String), PairMap>> = Lazy::new(load_confusion_data);

fn read_name(data: &[u8], offset: usize) -> Option<(String, usize)> {
    let len = *data.get(offset)? as usize;
    let start = offset + 1;
    let bytes = data.get(start..start + len)?;
    Some((String::from_utf8_lossy(bytes).into_owned(), start + len))
}

fn load_confusion_data() -> HashMap<(String, String), PairMap> {
    let mut maps: HashMap<(String, String), PairMap> = HashMap::new();
    if CONFUSION_BIN.len() < 2 {
        return maps;
    }
    let num_pairs = u16::from_be_bytes([CONFUSION_BIN[0], CONFUSION_BIN[1]]) as usize;
    let mut offset = 2usize;

    for _ in 0..num_pairs {
        let (name_a, next) = match read_name(CONFUSION_BIN, offset) {
            Some(value) => value,
            None => break,
        };
        offset = next;
        let (name_b, next) = match read_name(CONFUSION_BIN, offset) {
            Some(value) => value,
            None => break,
        };
        offset = next;

        let num_diffs = match CONFUSION_BIN.get(offset) {
            Some(&count) => count as usize,
            None => break,
        };
        offset += 1;

        let mut diff_bytes: Vec<u8> = Vec::with_capacity(num_diffs);
        let mut cat_a = [29u8; 256];
        let mut cat_b = [29u8; 256];
        let mut member = [false; 256];
        for _ in 0..num_diffs {
            let entry = match CONFUSION_BIN.get(offset..offset + 3) {
                Some(entry) => entry,
                None => break,
            };
            offset += 3;
            let byte = entry[0];
            diff_bytes.push(byte);
            member[byte as usize] = true;
            cat_a[byte as usize] = entry[1];
            cat_b[byte as usize] = entry[2];
        }

        // Normalize the pair names to canonical codec names so pipeline
        // results match without a translation step.
        let canonical_a = lookup_encoding(&name_a).unwrap_or(&name_a).to_string();
        let canonical_b = lookup_encoding(&name_b).unwrap_or(&name_b).to_string();

        maps.insert(
            (canonical_a.clone(), canonical_b.clone()),
            PairMap {
                enc_a: canonical_a,
                enc_b: canonical_b,
                diff_bytes,
                member,
                cat_a,
                cat_b,
            },
        );
    }

    maps
}

fn find_pair<'a>(
    maps: &'a HashMap<(String, String), PairMap>,
    enc_a: &str,
    enc_b: &str,
) -> Option<&'a PairMap> {
    if let Some(pair) = maps.get(&(enc_a.to_string(), enc_b.to_string())) {
        return Some(pair);
    }
    maps.get(&(enc_b.to_string(), enc_a.to_string()))
}

fn context_preference(
    category: u8,
    left: u8,
    right: u8,
    case_table: Option<&EncodingTables>,
) -> i32 {
    let preference = category_preference(category);
    if !category_is_letter(category) {
        return preference;
    }
    let (left_kind, right_kind) = match case_table {
        Some(table) => (table.case[left as usize], table.case[right as usize]),
        None => (0, 0),
    };
    if left_kind == 0 && right_kind == 0 {
        return IMPLAUSIBLE_LETTER_PREFERENCE;
    }
    if category_is_lowercase(category) && right_kind == 1 {
        return IMPLAUSIBLE_LETTER_PREFERENCE;
    }
    preference
}

fn is_punctuation(category: u8) -> bool {
    (11..=17).contains(&category)
}

/// Result of the context-aware category vote.
struct Vote {
    winner: Option<String>,
    #[allow(dead_code)]
    margin: i32,
    demotion_margin: i32,
    events: i32,
}

/// Context-aware category voting over every occurrence of a distinguishing byte.
fn vote_with_margin(data: &[u8], pair: &PairMap) -> Vote {
    let case_a = tables_for(&pair.enc_a);
    let case_b = tables_for(&pair.enc_b);

    let mut occurrences = [0usize; 256];
    let mut votes_a = 0i32;
    let mut votes_b = 0i32;
    let mut demotion_a = 0i32;
    let mut demotion_b = 0i32;
    let mut events_a = 0i32;
    let mut events_b = 0i32;
    let end = data.len().saturating_sub(1);

    for pos in 0..data.len() {
        let byte = data[pos];
        if !pair.is_diff(byte) {
            continue;
        }
        if occurrences[byte as usize] >= MAX_VOTE_OCCURRENCES {
            continue;
        }
        occurrences[byte as usize] += 1;

        let left = if pos > 0 { data[pos - 1] } else { 0 };
        let right = if pos < end { data[pos + 1] } else { 0 };
        let (cat_a, cat_b) = pair.categories(byte);

        let pref_a = context_preference(cat_a, left, right, case_a);
        let pref_b = context_preference(cat_b, left, right, case_b);

        if pref_a > pref_b {
            // A letter beating punctuation on naive preference is not
            // evidence: punctuation legitimately borders letters.  A letter
            // beating a *symbol* reading still counts.
            if !(category_is_letter(cat_a) && is_punctuation(cat_b)) {
                votes_a += pref_a - pref_b;
                if category_is_letter(cat_b) && pref_b == IMPLAUSIBLE_LETTER_PREFERENCE {
                    demotion_a += pref_a - pref_b;
                    events_a += 1;
                }
            }
        } else if pref_b > pref_a && !(category_is_letter(cat_b) && is_punctuation(cat_a)) {
            votes_b += pref_b - pref_a;
            if category_is_letter(cat_a) && pref_a == IMPLAUSIBLE_LETTER_PREFERENCE {
                demotion_b += pref_b - pref_a;
                events_b += 1;
            }
        }
    }

    if votes_a > votes_b {
        return Vote {
            winner: Some(pair.enc_a.clone()),
            margin: votes_a - votes_b,
            demotion_margin: demotion_a,
            events: events_a,
        };
    }
    if votes_b > votes_a {
        return Vote {
            winner: Some(pair.enc_b.clone()),
            margin: votes_b - votes_a,
            demotion_margin: demotion_b,
            events: events_b,
        };
    }
    Vote {
        winner: None,
        margin: 0,
        demotion_margin: 0,
        events: 0,
    }
}

/// Build a profile of only the bigrams that involve a distinguishing byte.
fn build_focused_profile(data: &[u8], pair: &PairMap) -> Option<BigramProfile> {
    if data.len() < 2 {
        return None;
    }
    if !data.iter().any(|&byte| pair.is_diff(byte)) {
        return None;
    }
    let models = get_models()?;
    let idf = &models.idf;

    let mut weighted: HashMap<usize, u32> = HashMap::new();
    for window in data.windows(2) {
        let (b1, b2) = (window[0], window[1]);
        if !pair.is_diff(b1) && !pair.is_diff(b2) {
            continue;
        }
        let idx = ((b1 as usize) << 8) | b2 as usize;
        *weighted.entry(idx).or_insert(0) += idf[idx] as u32;
    }
    if weighted.is_empty() {
        return None;
    }
    Some(BigramProfile::from_weighted_freq(&weighted))
}

/// Languages *enc* has a bigram model for.
fn modelled_languages(models: &ModelSet, enc: &str) -> HashSet<String> {
    let mut languages = HashSet::new();
    if let Some(variants) = models.variants(enc) {
        for variant in variants {
            if let Some(language) = variant.language.as_ref() {
                languages.insert(language.clone());
            }
        }
    }
    languages
}

/// Languages to score both sides under, or `None` for all variants.
fn comparable_languages(
    models: &ModelSet,
    enc_a: &str,
    enc_b: &str,
    languages: &HashSet<String>,
) -> Option<HashSet<String>> {
    if languages.is_empty() {
        return None;
    }
    let langs_a = modelled_languages(models, enc_a);
    let langs_b = modelled_languages(models, enc_b);
    let shared: HashSet<String> = langs_a.intersection(&langs_b).cloned().collect();
    if !languages.is_subset(&shared) {
        return None;
    }
    if langs_a.contains(ART_LANGUAGE) || langs_b.contains(ART_LANGUAGE) {
        let mut with_art = shared;
        with_art.insert(ART_LANGUAGE.to_string());
        return Some(with_art);
    }
    Some(shared)
}

/// Best bigram score for *enc*, restricted to *languages* when given.
fn best_variant_score(
    models: &ModelSet,
    profile: &BigramProfile,
    enc: &str,
    languages: Option<&HashSet<String>>,
) -> f64 {
    let variants = match models.variants(enc) {
        Some(variants) => variants,
        None => return 0.0,
    };

    let mut best = 0.0f64;
    for variant in variants {
        if let Some(languages) = languages {
            match variant.language.as_ref() {
                Some(language) if languages.contains(language) => {}
                _ => continue,
            }
        }
        let table = match models.tables.get(&variant.key) {
            Some(table) => table,
            None => continue,
        };
        let norm = models.norms.get(&variant.key).copied().unwrap_or(0.0);
        let score = score_with_profile(profile, table, norm);
        if score > best {
            best = score;
        }
    }
    best
}

/// Resolve a pair by re-scoring only the distinguishing bigrams.
fn resolve_by_bigram_rescore(
    data: &[u8],
    pair: &PairMap,
    languages: &HashSet<String>,
) -> Option<String> {
    let models = get_models()?;
    let profile = build_focused_profile(data, pair)?;
    let comparable = comparable_languages(&models, &pair.enc_a, &pair.enc_b, languages);

    let best_a = best_variant_score(&models, &profile, &pair.enc_a, comparable.as_ref());
    let best_b = best_variant_score(&models, &profile, &pair.enc_b, comparable.as_ref());

    if best_a > best_b {
        return Some(pair.enc_a.clone());
    }
    if best_b > best_a {
        return Some(pair.enc_b.clone());
    }
    None
}

/// Decide a pair on its distinguishing bytes: model rescore, then context.
/// Model scores below this are indistinguishable from "no evidence".
const SCORE_NOISE_FLOOR: f64 = 1e-6;

pub fn arbitrate_distinguishing_bytes(
    data: &[u8],
    enc_a: &str,
    enc_b: &str,
    diff_bytes: &[u8],
    languages_a: Option<&HashSet<String>>,
    languages_b: Option<&HashSet<String>>,
) -> Option<String> {
    let pair = pair_from_tables(enc_a, enc_b, diff_bytes);

    if let Some(models) = get_models() {
        if let Some(profile) = build_focused_profile(data, &pair) {
            let best_a = best_variant_score(&models, &profile, enc_a, languages_a);
            let best_b = best_variant_score(&models, &profile, enc_b, languages_b);
            // Two models that both explain nothing of the distinguishing
            // bigrams score at the noise floor.  The reference compares them
            // at exactly 0.0; floating-point drift here must not turn an
            // evidence-free pair into a verdict, so treat the floor as a tie
            // and let the category vote decide.
            let tiny = best_a < SCORE_NOISE_FLOOR && best_b < SCORE_NOISE_FLOOR;
            if !tiny {
                if best_a > best_b {
                    return Some(enc_a.to_string());
                }
                if best_b > best_a {
                    return Some(enc_b.to_string());
                }
            }
        }
    }

    vote_with_margin(data, &pair).winner
}

/// Byte-evidence winner between two encodings, or `None` when inconclusive.
pub fn confusion_pair_winner(
    data: &[u8],
    enc_x: &str,
    enc_y: &str,
    languages: &HashSet<String>,
) -> Option<String> {
    let pair = find_pair(&CONFUSION_MAPS, enc_x, enc_y)?;
    let vote = vote_with_margin(data, pair);

    if vote.winner.is_some()
        && vote.demotion_margin >= DECISIVE_VOTE_MARGIN
        && vote.events >= DECISIVE_MIN_EVENTS
        && pair.diff_bytes.len() < CROSS_FAMILY_MIN_DIFFS
    {
        return vote.winner;
    }

    let bigram_winner = resolve_by_bigram_rescore(data, pair, languages);
    if pair.diff_bytes.len() >= CROSS_FAMILY_MIN_DIFFS {
        // Cross-family pairs: overturning the ranking needs corroboration.
        if bigram_winner.is_some() && bigram_winner == vote.winner {
            return bigram_winner;
        }
        return None;
    }
    bigram_winner.or(vote.winner)
}

/// Resolve confusion between similar encodings in the top results.
pub fn resolve_confusion_groups(
    data: &[u8],
    results: Vec<DetectionResult>,
) -> Vec<DetectionResult> {
    if results.len() < 2 {
        return results;
    }
    let top = &results[0];
    let top_encoding = match top.encoding.as_deref() {
        Some(encoding) => encoding,
        None => return results,
    };
    // An art-model win (the zxx pseudo-language: no linguistic content) is
    // not up for linguistic-plausibility review.
    if top.language.as_deref() == Some(ART_LANGUAGE) {
        return results;
    }

    let top_conf = top.confidence;
    let floor = top_conf * CONFUSION_FLOOR_RATIO;
    let mut champion_idx = 0usize;
    let mut champion_encoding = top_encoding.to_string();
    let mut champion_language = top.language.clone();

    for i in 1..results.len() {
        let candidate = &results[i];
        let candidate_encoding = match candidate.encoding.as_deref() {
            Some(encoding) => encoding,
            None => continue,
        };

        let in_band = i == 1 || top_conf - candidate.confidence <= CONFUSION_BAND;
        if !in_band && (top_conf >= STRICT_TIER_MAX_CONF || candidate.confidence < floor) {
            break;
        }

        let pair = match find_pair(&CONFUSION_MAPS, &champion_encoding, candidate_encoding) {
            Some(pair) => pair,
            None => continue,
        };

        let vote = vote_with_margin(data, pair);
        let decisive_demotion = vote.winner.is_some()
            && vote.demotion_margin >= DECISIVE_VOTE_MARGIN
            && vote.events >= DECISIVE_MIN_EVENTS
            && pair.diff_bytes.len() < CROSS_FAMILY_MIN_DIFFS;

        let winner: Option<String> = if decisive_demotion {
            vote.winner.clone()
        } else {
            let mut languages: HashSet<String> = HashSet::new();
            if let Some(language) = champion_language.as_ref() {
                languages.insert(language.clone());
            }
            if let Some(language) = candidate.language.as_ref() {
                languages.insert(language.clone());
            }
            let bigram_winner = resolve_by_bigram_rescore(data, pair, &languages);
            if in_band && pair.diff_bytes.len() < CROSS_FAMILY_MIN_DIFFS {
                bigram_winner.or(vote.winner.clone())
            } else if bigram_winner.is_some() && bigram_winner == vote.winner {
                bigram_winner
            } else {
                None
            }
        };

        if winner.as_deref() != Some(candidate_encoding) {
            continue;
        }

        if in_band {
            // In-band promotion: trust it and stop.
            let mut promoted = Vec::with_capacity(results.len());
            promoted.push(DetectionResult::new_with_mime(
                Some(candidate_encoding),
                top_conf,
                candidate.language.as_deref(),
                candidate.mime_type.as_deref(),
            ));
            for (j, result) in results.iter().enumerate() {
                if j != i {
                    promoted.push(result.clone());
                }
            }
            return promoted;
        }

        // Strict-tier promotion: the new champion must defend against the
        // remaining candidates (king of the hill).
        champion_idx = i;
        champion_encoding = candidate_encoding.to_string();
        champion_language = candidate.language.clone();
    }

    if champion_idx == 0 {
        return results;
    }

    let champion = &results[champion_idx];
    let mut promoted = Vec::with_capacity(results.len());
    promoted.push(DetectionResult::new_with_mime(
        champion.encoding.as_deref(),
        top_conf,
        champion.language.as_deref(),
        champion.mime_type.as_deref(),
    ));
    for (j, result) in results.iter().enumerate() {
        if j != champion_idx {
            promoted.push(result.clone());
        }
    }
    promoted
}

/// Distinguishing high bytes for a pair the confusion maps do not cover.
pub fn differing_bytes(enc_a: &str, enc_b: &str) -> Vec<u8> {
    differing_high_bytes(enc_a, enc_b)
}
